// Simple Asteroid Dodge game targeting canvas with id="game"
// Controls: ArrowLeft / ArrowRight or A/D keys

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width;
  const height = canvas.height;

  const ship = {
    w: 40,
    h: 20,
    x: width / 2 - 20,
    y: height - 30,
    speed: 5,
    color: '#0ff',
  };

  let asteroids = [];
  const asteroidSpawnInterval = 1000; // ms
  let lastSpawn = 0;

  let health = 3;
  let score = 0;
  let lastTime = 0;

  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function spawnAsteroid() {
    const size = Math.random() * 20 + 10;
    asteroids.push({
      x: Math.random() * (width - size),
      y: -size,
      w: size,
      h: size,
      speed: Math.random() * 2 + 1,
      color: '#f55',
    });
  }

  function update(dt) {
    // ship movement
    if (keys['ArrowLeft'] || keys['a']) ship.x -= ship.speed;
    if (keys['ArrowRight'] || keys['d']) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(width - ship.w, ship.x));

    // asteroids
    asteroids.forEach(a => a.y += a.speed);
    // remove off‑screen
    asteroids = asteroids.filter(a => a.y < height);

    // collision detection
    for (const a of asteroids) {
      if (
        a.x < ship.x + ship.w &&
        a.x + a.w > ship.x &&
        a.y < ship.y + ship.h &&
        a.y + a.h > ship.y
      ) {
        health--;
        // remove this asteroid
        a.y = height + 1;
        if (health <= 0) {
          // game over – stop animation
          cancelAnimationFrame(animId);
          alert('Game Over! Score: ' + Math.floor(score));
          return;
        }
      }
    }
    // score as time survived
    score += dt / 1000;
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // ship
    ctx.fillStyle = ship.color;
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // asteroids
    asteroids.forEach(a => {
      ctx.fillStyle = a.color;
      ctx.beginPath();
      ctx.arc(a.x + a.w / 2, a.y + a.h / 2, a.w / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    // health bar
    ctx.fillStyle = '#0f0';
    for (let i = 0; i < health; i++) {
      ctx.fillRect(10 + i * 15, 10, 10, 10);
    }
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), width - 100, 20);
  }

  let animId;
  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (timestamp - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = timestamp;
    }
    update(dt);
    draw();
    animId = requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
